SELECT NULL BETWEEN (NULL >= nullif(-791.2, -863)) AND abs('nu'), x'5cd8a4';
SELECT id, iif(-80.7, NULL, -488) IN (c2, -2.5, NULL), CASE WHEN coalesce(id, ('xi' << ref)) THEN id IN (CASE WHEN x'dbabc9' THEN NULL ELSE c1 END, NULL, 'psi') ELSE c0 END FROM t1 ORDER BY id, c0, c1, c2, ref DESC;
