SELECT id, id, ref BETWEEN CASE WHEN c2 THEN c2 ELSE c0 END AND 'epsilon' BETWEEN ref AND c2 BETWEEN abs(c1) IN (c1 IN (c1, -0.0, NULL), '0x1F', x'025cfa') AND c2 FROM t1 ORDER BY id, c0, c1 DESC, c2, ref;
