WITH RECURSIVE f(n, a, b) AS (SELECT 1, 0, 1 UNION ALL SELECT n + 1, b, a + b FROM f WHERE n < 35) SELECT n, a FROM f ORDER BY n DESC LIMIT 5;
WITH RECURSIVE s(x) AS (SELECT 5 UNION ALL SELECT CASE WHEN x % 2 THEN 3 * x + 1 ELSE x / 2 END FROM s WHERE x <> 1) SELECT count(*), max(x), group_concat(x) FROM s;
WITH a(x) AS (VALUES(1),(2),(3)), b(y) AS (SELECT x * x FROM a) SELECT x, y FROM a, b ORDER BY x, y;
SELECT printf('%5.2f', 1), round(1, 0), 1 * -5, 1 / -2.5, CAST(1 AS TEXT), 1 + 0.0;
SELECT json_valid('{"a":1,"b":[1,2,{"c":"x"}],"d":null,"e":1.5e3}'), json('{"a":1,"b":[1,2,{"c":"x"}],"d":null,"e":1.5e3}'), json_type('{"a":1,"b":[1,2,{"c":"x"}],"d":null,"e":1.5e3}'), json_array_length('{"a":1,"b":[1,2,{"c":"x"}],"d":null,"e":1.5e3}'), json_extract('{"a":1,"b":[1,2,{"c":"x"}],"d":null,"e":1.5e3}', '$.a', '$[1]', '$.b[2].c'), '{"a":1,"b":[1,2,{"c":"x"}],"d":null,"e":1.5e3}' -> '$.b', '{"a":1,"b":[1,2,{"c":"x"}],"d":null,"e":1.5e3}' ->> '$.n.m.o';
